(function(){"use strict";var DEFAULT_KEYWORD="Cheap Flights";function getParam(names){var params=new URLSearchParams(window.location.search);for(var i=0;i<names.length;i++){var v=params.get(names[i]);if(v&&v.trim().length)return v;}
return null;}
function cleanKeyword(raw){var text=decodeURIComponent(raw.replace(/\+/g," "));text=text.replace(/[_\-]+/g," ").replace(/\s+/g," ").trim();var small=["to","from","and","the","in","of","a","for"];var words=text.split(" ").map(function(w,i){var lw=w.toLowerCase();if(i!==0&&small.indexOf(lw)>-1)return lw;return lw.charAt(0).toUpperCase()+lw.slice(1);});return words.join(" ");}
function initDynamicKeyword(){var raw=getParam(["keywords","kw","utm_term","keyword","k"]);var keyword=raw?cleanKeyword(raw):DEFAULT_KEYWORD;document.querySelectorAll("[data-kw]").forEach(function(el){if(el.tagName==="INPUT"||el.tagName==="TEXTAREA"){el.value=keyword;}else{el.textContent=keyword;}});document.querySelectorAll("[data-kw-lower]").forEach(function(el){if(el.tagName==="INPUT"||el.tagName==="TEXTAREA"){el.value=keyword.toLowerCase();}else{el.textContent=keyword.toLowerCase();}});if(document.title.indexOf("{kw}")>-1){document.title=document.title.replace("{kw}",keyword);}
var metaDesc=document.querySelector('meta[name="description"]');if(metaDesc&&metaDesc.getAttribute("content").indexOf("{kw}")>-1){metaDesc.setAttribute("content",metaDesc.getAttribute("content").replace("{kw}",keyword));}}
function initNav(){var toggle=document.querySelector(".nav-toggle");var nav=document.querySelector(".main-nav");if(!toggle||!nav)return;toggle.addEventListener("click",function(){var open=nav.classList.toggle("nav-open");toggle.setAttribute("aria-expanded",open?"true":"false");});nav.querySelectorAll("a").forEach(function(link){link.addEventListener("click",function(){nav.classList.remove("nav-open");toggle.setAttribute("aria-expanded","false");});});}
function initFaq(){document.querySelectorAll(".faq-item").forEach(function(item){var q=item.querySelector(".faq-q");if(!q)return;q.setAttribute("aria-expanded",item.classList.contains("open")?"true":"false");q.addEventListener("click",function(){var isOpen=item.classList.contains("open");document.querySelectorAll(".faq-item.open").forEach(function(openItem){if(openItem!==item){openItem.classList.remove("open");openItem.querySelector(".faq-q").setAttribute("aria-expanded","false");}});item.classList.toggle("open",!isOpen);q.setAttribute("aria-expanded",(!isOpen).toString());});});}
function initBoard(){var track=document.querySelector(".board-track");if(!track)return;track.innerHTML+=track.innerHTML;}
function initLeadForms(){document.querySelectorAll("form.lead-form").forEach(function(form){form.addEventListener("submit",function(e){e.preventDefault();var fieldsWrap=form.querySelector(".lead-form-fields");var success=form.querySelector(".form-success");var errorBox=form.querySelector(".form-error");var submitBtn=form.querySelector('button[type="submit"]');var originalLabel=submitBtn?submitBtn.innerHTML:"";if(errorBox)errorBox.classList.remove("visible");if(submitBtn){submitBtn.disabled=true;submitBtn.textContent="Sending…";}
fetch(form.action,{method:"POST",headers:{Accept:"application/json"},body:new FormData(form),}).then(function(res){if(!res.ok)throw new Error("Network response was not OK");if(success){var nameInput=form.querySelector('input[name="name"]');var nameSlot=success.querySelector(".success-name");if(nameInput&&nameInput.value.trim()&&nameSlot){var firstName=nameInput.value.trim().split(" ")[0];nameSlot.textContent=", "+firstName;}}
if(fieldsWrap)fieldsWrap.style.display="none";if(success)success.classList.add("active");}).catch(function(){if(errorBox)errorBox.classList.add("visible");if(submitBtn){submitBtn.disabled=false;submitBtn.innerHTML=originalLabel;}});});});}
function initSwapButtons(){document.querySelectorAll(".swap-btn").forEach(function(btn){btn.addEventListener("click",function(){var row=btn.closest(".swap-row");if(!row)return;var fromInput=row.querySelector('input[name="from"]');var toInput=row.querySelector('input[name="to"]');if(fromInput&&toInput){var tmp=fromInput.value;fromInput.value=toInput.value;toInput.value=tmp;}
btn.classList.toggle("swapped");});});}
function initTripType(){document.querySelectorAll('select[name="trip_type"]').forEach(function(select){var form=select.closest("form");if(!form)return;var returnField=form.querySelector('input[name="return_date"]');if(!returnField)return;var returnWrap=returnField.closest(".field");function sync(){var isOneWay=select.value==="One Way";if(returnWrap)returnWrap.style.visibility=isOneWay?"hidden":"visible";returnField.disabled=isOneWay;}
select.addEventListener("change",sync);sync();});}
function initFareModal(){var overlay=document.getElementById("fareModal");if(!overlay)return;var closeBtn=overlay.querySelector(".modal-close");var airlineField=overlay.querySelector('input[name="airline_interest"]');var priceField=overlay.querySelector('input[name="fare_price"]');var nameSlot=overlay.querySelector(".modal-airline-name");var fareChip=document.getElementById("modalFareChip");var farePriceSlot=overlay.querySelector(".modal-fare-price");var lastFocused=null;function openModal(airlineName,price){lastFocused=document.activeElement;if(airlineField)airlineField.value=airlineName||"";if(priceField)priceField.value=price||"";if(nameSlot)nameSlot.textContent=airlineName?" — "+airlineName:"";if(fareChip&&farePriceSlot){if(price){farePriceSlot.textContent=(airlineName?airlineName+" ":"")+"from "+price;fareChip.style.display="flex";}else{fareChip.style.display="none";}}
overlay.classList.add("open");document.body.classList.add("modal-open");var firstInput=overlay.querySelector("input:not([type=hidden]), select");if(firstInput)firstInput.focus();}
function closeModal(){overlay.classList.remove("open");document.body.classList.remove("modal-open");if(lastFocused&&typeof lastFocused.focus==="function")lastFocused.focus();}
document.querySelectorAll(".get-discount-btn").forEach(function(btn){btn.addEventListener("click",function(){openModal(btn.getAttribute("data-airline"),btn.getAttribute("data-price"));});});if(closeBtn)closeBtn.addEventListener("click",closeModal);overlay.addEventListener("click",function(e){if(e.target===overlay)closeModal();});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&overlay.classList.contains("open"))closeModal();});}
function initDatePickers(){document.querySelectorAll('input[type="date"]').forEach(function(input){input.addEventListener("click",function(){if(typeof input.showPicker==="function"){try{input.showPicker();}catch(err){}}});});}
var CAPTURED_GCLID=null;function initGclidCapture(){var params=new URLSearchParams(window.location.search);var gclid=params.get("gclid");var CONSENT_KEY="ff_cookie_consent";var GCLID_KEY="ff_gclid";if(gclid){CAPTURED_GCLID=gclid;try{if(localStorage.getItem(CONSENT_KEY)==="accepted"){localStorage.setItem(GCLID_KEY,gclid);}}catch(err){}}else{try{if(localStorage.getItem(CONSENT_KEY)==="accepted"){CAPTURED_GCLID=localStorage.getItem(GCLID_KEY);}}catch(err){}}
if(CAPTURED_GCLID){document.querySelectorAll('input[name="gclid"]').forEach(function(el){el.value=CAPTURED_GCLID;});}}
function initCookieBanner(){var banner=document.getElementById("cookieBanner");if(!banner)return;var STORAGE_KEY="ff_cookie_consent";var accept=document.getElementById("cookieAccept");var decline=document.getElementById("cookieDecline");try{if(!localStorage.getItem(STORAGE_KEY)){window.setTimeout(function(){banner.classList.add("visible");},600);}}catch(err){}
function dismiss(value){try{localStorage.setItem(STORAGE_KEY,value);if(value==="accepted"&&CAPTURED_GCLID){localStorage.setItem("ff_gclid",CAPTURED_GCLID);}}catch(err){}
banner.classList.remove("visible");}
if(accept)accept.addEventListener("click",function(){dismiss("accepted");});if(decline)decline.addEventListener("click",function(){dismiss("declined");});}
function initHeaderScroll(){var header=document.querySelector(".site-header");var mobileBar=document.querySelector(".mobile-bar");var revealed=false;function onScroll(){if(header){header.classList.toggle("scrolled",window.scrollY>12);}
if(mobileBar&&!revealed&&window.scrollY>80){mobileBar.classList.add("visible");revealed=true;}}
window.addEventListener("scroll",onScroll,{passive:true});onScroll();}
function initReveal(){var selector=".card, .route-card, .testi, .step, .section-head, .cta-band, .lead-card";var els=Array.prototype.slice.call(document.querySelectorAll(selector));if(!els.length)return;if(!("IntersectionObserver"in window)||window.matchMedia("(prefers-reduced-motion: reduce)").matches){return;}
var seen=new Map();els.forEach(function(el){el.classList.add("reveal-init");var parent=el.parentElement;var siblingIndex=seen.get(parent)||0;seen.set(parent,siblingIndex+1);el.style.transitionDelay=Math.min(siblingIndex%4,4)*90+"ms";});var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("revealed");observer.unobserve(entry.target);}});},{threshold:0.12,rootMargin:"0px 0px -40px 0px"});els.forEach(function(el){observer.observe(el);});}
function initCountUp(){var els=document.querySelectorAll("[data-countup]");if(!els.length)return;function animate(el){var target=parseInt(el.getAttribute("data-countup"),10)||0;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches){el.textContent=target.toLocaleString("en-GB");return;}
var duration=1400;var start=null;function step(ts){if(start===null)start=ts;var progress=Math.min((ts-start)/duration,1);var eased=1-Math.pow(1-progress,3);el.textContent=Math.round(eased*target).toLocaleString("en-GB");if(progress<1)window.requestAnimationFrame(step);}
window.requestAnimationFrame(step);}
if(!("IntersectionObserver"in window)){els.forEach(animate);return;}
var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){animate(entry.target);observer.unobserve(entry.target);}});},{threshold:0.5});els.forEach(function(el){observer.observe(el);});}
function renderTurnstileWidgets(){if(typeof turnstile==="undefined")return;document.querySelectorAll(".cf-turnstile").forEach(function(container){if(container.getAttribute("data-rendered")==="true")return;var form=container.closest("form");var submitBtn=form?form.querySelector('button[type="submit"]'):null;var tokenField=form?form.querySelector('input[name="cf-turnstile-response"]'):null;turnstile.render(container,{sitekey:container.getAttribute("data-sitekey"),callback:function(token){if(tokenField)tokenField.value=token;if(submitBtn)submitBtn.disabled=false;},"expired-callback":function(){if(tokenField)tokenField.value="";if(submitBtn)submitBtn.disabled=true;},"error-callback":function(){if(tokenField)tokenField.value="";if(submitBtn)submitBtn.disabled=true;},});container.setAttribute("data-rendered","true");});}
window.onloadTurnstile=function(){renderTurnstileWidgets();};function initTurnstile(){var overlay=document.getElementById("fareModal");if(overlay){var observer=new MutationObserver(function(){if(overlay.classList.contains("open"))renderTurnstileWidgets();});observer.observe(overlay,{attributes:true,attributeFilter:["class"]});}
if(typeof turnstile!=="undefined")renderTurnstileWidgets();}
document.addEventListener("DOMContentLoaded",function(){initDynamicKeyword();initGclidCapture();initNav();initFaq();initBoard();initLeadForms();initSwapButtons();initTripType();initDatePickers();initFareModal();initTurnstile();initCookieBanner();initHeaderScroll();initReveal();initCountUp();});})();